Let $\mathbb{N} := \{0,1,2,\hdots\}$ and let $\|\cdot\|$ be the induced norm of an inner product $\langle \cdot, \cdot\rangle$ on $\mathbb{R}^n$. Throughout this paper, we fix an arbitrary o-minimal structure on the real field (see Definition \ref{def:o-minimal}), and say that sets or functions are definable if they are definable in this structure. For readers not familiar with o-minimal structures, note that seemingly all objective functions used in practice are definable in some o-minimal structure. Low-rank matrix recovery (for e.g., matrix factorization, matrix completion, and matrix sensing) and deep neural networks are no exception \cite[Section 6.2]{bolte2020conservative}.


We begin by stating some standard definitions. Let $B(a,r)$ and $S(a,r)$ respectively denote the closed ball and the sphere of center $a\in \mathbb{R}^n$ and radius $r \geqslant 0$.

\begin{definition}
\label{def:lipschitz}
A function $f:\mathbb{R}^n\rightarrow\mathbb{R}^m$ is locally Lipschitz if for all $a \in \mathbb{R}^n$, there exist $r>0$ and $L>0$ such that 
\begin{equation*}
        \forall x,y \in B(a,r), ~~~ \|f(x)-f(y)\| \leqslant L \|x-y\|.
    \end{equation*}
\end{definition}

\begin{definition}
    \label{def:Clarke}
    \cite[Chapter 2]{clarke1990}
    Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function. The Clarke subdifferential is the set-valued mapping $\partial f:\mathbb{R}^n\rightrightarrows\mathbb{R}^n$ defined for all $x \in \mathbb{R}^n$ by
    $\partial f(x) := \{ s \in \mathbb{R}^n : f^\circ(x,h) \geqslant \langle s , h \rangle, ~ \forall h\in \mathbb{R}^n \}$ where
\begin{equation*}
    f^\circ(x,h) := \limsup_{\tiny\begin{array}{c} y\rightarrow x \\
    t \searrow 0
    \end{array}
    } \frac{f(y+th)-f(y)}{t}.
\end{equation*}
\end{definition}

We say that $x \in \mathbb{R}^n$ is critical if $0 \in \partial f(x)$. If $f$ is continuously differentiable in a neighborhood of $x \in \mathbb{R}^n$, then $\partial f(x) = \{\nabla f(x)\}$ \cite[2.2.4 Proposition p. 33]{clarke1990}.


\begin{definition}
    \label{def:absolute_continuity} 
    \cite[Definition 1 p. 12]{aubin1984differential}
    Given some real numbers $a\leqslant b$, a function $x:[a,b]\rightarrow\mathbb{R}^n$ is absolutely continuous if for all $\epsilon>0$, there exists $\delta>0$ such that, for any finite collection of disjoint subintervals $[a_1,b_1],\hdots,[a_m,b_m]$ of $[a,b]$ such that $\sum_{i=1}^m b_i-a_i \leqslant \delta$, we have $\sum_{i=1}^m \|x(b_i) - x(a_i)\| \leqslant \epsilon$.
\end{definition}

By virtue of \cite[Theorem 20.8]{nielsen1997introduction}, $x:[a,b]\rightarrow\mathbb{R}^n$ is absolutely continuous if and only if it is differentiable almost everywhere on $(a,b)$, its derivative $x'(\cdot)$ is Lebesgue integrable, and $x(t) - x(a) = \int_a^t x'(\tau)d\tau$ for all $t\in [a,b]$. Given a noncompact interval $I$ of $\mathbb{R}$, $x:I\rightarrow \mathbb{R}^n$ is absolutely continuous if it is absolutely continuous on all compact subintervals of $I$. Given an interval $I$ of $\mathbb{R}$, let $\mathcal{A}(I,\mathbb{R}^n)$ be the set of absolutely continuous functions defined from $I$ to $\mathbb{R}^n$.

\begin{definition}
\label{def:trajectory}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function. Let $(S,\leqslant)$ be the set of absolutely continuous functions $x:[0,T)\rightarrow\mathbb{R}^n$ where $0<T\leqslant \infty$ such that  
\begin{equation*}
    x'(t) \in -\partial f(x(t)), ~~~\mathrm{for~a.e.}~t\in (0,T),
\end{equation*}
equipped with the partial order $\leqslant$ defined by $x_1:[0,T_1)\rightarrow\mathbb{R}^n$ is less than or equal to $x_2:[0,T_2)\rightarrow\mathbb{R}^n$ if and only if $T_1\leqslant T_2$ and $x_1(t) = x_2(t)$ for all $t\in [0,T_1)$. 
We refer to maximal elements of $(S,\leqslant)$ as continuous subgradient trajectories.
\end{definition}

We say that a continuous subgradient trajectory is globally defined if it is of the form $x:[0,T)\rightarrow\mathbb{R}^n$ where $T=\infty$. We refer to discrete subgradient trajectories as sequences $(x_k)_{k\in \mathbb{N}}$ in $\mathbb{R}^n$ such that $x_{k+1} \in x_k -\alpha_k \partial f(x_k)$ for all $k\in \mathbb{N}$ for some $\alpha_0,\alpha_1,\alpha_2,\hdots>0$. When $f$ is continuously differentiable, we refer to subgradient trajectories as  gradient trajectories.

\begin{definition}
\label{def:bounded_trajectory}
A continuous subgradient trajectory $x: [0,T) \rightarrow \mathbb{R}^n$ where $0< T\leqslant \infty$ is bounded if there exists $c>0$ such that $\|x(t)\| \leqslant c$ for all $t\in [0,T)$.
\end{definition}


\begin{remark}
\label{rem:tracking}
If $X_0$ is a singleton $\{x_0\}$ and $x:[0,\hat{T})\rightarrow \mathbb{R}^n$ is a gradient trajectory initialized at $x_0$, then one may remove the assumption that $f$ is lower bounded in Proposition \ref{prop:tracking} and instead require that $T \in (0,\hat{T})$. In that case, $\sigma_T(X_0)=\int_0^T \|x'(t)\|dt < \infty$ since $\nabla f$ is Lipschitz continuous on the bounded set $x([0,T])$.
\end{remark}

\begin{definition}
\label{def:o-minimal}
\cite[Definition p. 503-506]{van1996geometric}
An o-minimal structure on the real field is a sequence $S = (S_k)_{k \in \mathbb{N}}$ such that for all $k \in \mathbb{N}$:
\begin{enumerate}
    \item $S_k$ is a boolean algebra of subsets of $\mathbb{R}^k$, with $\mathbb{R}^k \in S_k$;
    \item $S_k$ contains the diagonal $\{(x_1,\hdots,x_k) \in \mathbb{R}^k : x_i = x_j\}$ for $1\leqslant i<j \leqslant k$;
    \item If $A\in S_k$, then $A\times \mathbb{R}$ and $\mathbb{R}\times A$ belong to $S_{k+1}$;
    \item If $A \in S_{k+1}$ and $\pi:\mathbb{R}^{k+1}\rightarrow\mathbb{R}^k$ is the projection onto the first $k$ coordinates, then $\pi(A) \in S_k$;
    \item $S_3$ contains the graphs of addition and multiplication;
    \item $S_1$ consists exactly of the finite unions of open intervals and singletons. 
\end{enumerate}
\end{definition}

A subset $A$ of $\mathbb{R}^n$ is definable in an o-minimal structure $(S_k)_{k\in\mathbb{N}}$ if $A \in S_k$. A function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ is definable in an o-minimal structure if its graph, that is to say $\{ (x,t) \in \mathbb{R}^{n+1} : f(x)=t \}$, is definable in that structure.


We next state the uniform Kurdyka-\L{}ojasiewicz inequality. Given a subset of $S$ of $\mathbb{R}^n$, let $\mathring{S}$ and $\overline{S}$ denote the interior and closure of $S$ in $\mathbb{R}^n$ respectively. A function $\psi:S \rightarrow S$ is a homeomorphism if it is a continuous bijection and the inverse function $\psi^{-1}$ is continuous. $\psi:S \rightarrow S$ is a diffeomorphism if $\mathring{S} \neq \emptyset$, $\psi$ is a homeomorphism, and both $\psi$ and $\psi^{-1}$ are continuously differentiable on $\mathring{S}$. Given $x\in \mathbb{R}^n$, consider the distance of $x$ to $S$ defined by $d(x,S) := \inf \{ \|x-y\| : y \in S \}$. Given a locally Lipschitz function $f:\mathbb{R}^n\rightarrow\mathbb{R}$, a real number $v$ is critical value of $f$ in $S$ if there exists $x \in S$ such that $v = f(x)$ and $0\in \partial f(x)$. Given a set-valued mapping $F:\mathbb{R}^n\rightrightarrows\mathbb{R}^m$ and $y \in \mathbb{R}^m$, let $F^{-1}(y) := \{ x \in \mathbb{R}^n : F(x) \ni y \}$.


We say that $\psi$ in Proposition \ref{prop:KL} is a desingularizing function of $f$ on $X$. In order to prove Proposition \ref{prop:length_continuous}, we recall the following result.


An immediate consequence of Propositions \ref{prop:length_continuous} and \ref{prop:length_discrete} is that bounded continuous subgradient trajectories and bounded discrete gradient trajectories have finite length, as is well known. An easy fact that we will not prove here is that continuous subgradient trajectories of finite length converge to critical points of the objective function under the sole assumption that it is locally Lipschitz. The same holds for discrete subgradient trajectories if the step sizes are not summable.

