\begin{theorem}
\label{thm:convergence}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a definable differentiable function whose gradient is locally Lipschitz. The following statements are equivalent:
\begin{enumerate}
    \item For all $x_0 \in \mathbb{R}^n$, there exist $\bar{\alpha}>0$ and $c>0$ such that for all $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by 
    \begin{equation}
    \label{eq:gradient_method}
        x_{k+1} = x_k - \alpha_k \nabla f(x_k), ~~~\forall k \in \mathbb{N},
    \end{equation}
    satisfies $\|x_k\|\leqslant c$ for all $k \in \mathbb{N}$.
    \item For all $0< T \leqslant \infty$ and any differentiable function $x:[0,T)\rightarrow\mathbb{R}^n$ such that
    \begin{equation*}
        x'(t) = -\nabla f(x(t)), ~~~ \forall t \in (0,T),
    \end{equation*}
    there exists $c>0$ such that $\|x(t)\| \leqslant c$ for all $t\in [0,T)$.
    \item For any bounded subset $X_0$ of $\mathbb{R}^n$, there exist $\bar{\alpha}>0$ and $c>0$ such that, for all $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$ and $x_0 \in X_0$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by \eqref{eq:gradient_method} obeys 
    \begin{equation*}
        \sum_{k=0}^{\infty} \|x_{k+1}-x_k\| \leqslant c.
    \end{equation*}
\end{enumerate}
\end{theorem}

