    & = \sqrt{T} \sqrt{ -\int_0^T \langle \nabla f(x(t)), x'(t) \rangle dt} \label{eq:length_finite_smooth_b} \\
    & = \sqrt{T} \sqrt{ -\int_0^T (f \circ x)'(t) dt} \label{eq:length_finite_smooth_c} \\
    & = \sqrt{T} \sqrt{ f(x(0)) - f(x(T))} \label{eq:length_finite_smooth_d} \\
    & \leqslant \sqrt{T\left(\sup_{X_0} f - \inf_{\mathbb{R}^n} f\right)} < \infty. \label{eq:length_finite_smooth_e}
\end{align}
\end{subequations}
Indeed, \eqref{eq:length_finite_smooth_a} is due to the Cauchy-Schwarz inequality. \eqref{eq:length_finite_smooth_e} holds because $X_0$ is bounded and $f$ is lower bounded.

It is easy to check that $L$ and $ML$ are respectively Lipschitz and gradient Lipschitz constants on $[0,T]$ of all continuous gradient trajectories of $f$ initialized in $X_0$. Indeed, let $x:\mathbb{R}_+\rightarrow \mathbb{R}^n$ be a continuous gradient trajectory initialized in $X_0$. Since $x(t) \in B(X_0,\sigma_T(X_0))$ for all $t\in [0,T]$, we have $\|x'(t)\| = \|\nabla f(x(t))\| \leqslant L$. By the mean value theorem \cite[5.19 Theorem]{rudin1964principles}, for all $s,t \in [0,T]$ we have $\|x'(t)-x'(s)\| = \|\nabla f(x(t)) - \nabla f(x(s))\| \leqslant M \|x(t)-x(s)\| \leqslant M L |t-s|$. As a byproduct, we get the Taylor bound
\begin{subequations}
    \begin{align}
    \|x(t)-x(s) - x'(s)(t-s)\| & = \left\| \int_s^t (x'(\tau) - x'(s)) d\tau \right\| \\
    & \leqslant \left| \int_s^t \| x'(\tau) - x'(s) \| d\tau \right| \\
    & \leqslant \left|\int_s^t ML | \tau - s | d\tau \right| \\
    & = \frac{ML}{2}(t-s)^2. \label{eq:local_error}
    \end{align}
\end{subequations}

Let $\epsilon \in (0,1)$ and let $\bar{\alpha} := 2\epsilon e^{-MT}/(LMT)$. Consider $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$ and a sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ such that $x_{k+1} = x_k - \alpha_k \nabla f(x_k)$ for all $k \in \mathbb{N}$ and $x_0 \in X_0$. Let $x:\mathbb{R}_+\rightarrow \mathbb{R}^n$ be the unique continuous gradient trajectory of $f$ initialized at $x_0$. Let $t_0:=0$ and $t_k := \alpha_0+\cdots+\alpha_{k-1}$ when $k\in \mathbb{N}^*$ so that $\|x_0 - x(t_0)\| = 0 \leqslant \epsilon$. Assume that \eqref{eq:tracking} holds up to some index $K$. For $k=0,\hdots,K$, we have
\begin{subequations}
    \begin{align}
        \|x_{k+1} - x(t_{k+1})\| = &  ~\| x_k - \alpha_k \nabla f(x_k) - x(t_{k+1}) \| \label{local_a} \\[2mm]
        \leqslant  & ~ \| x_k - \alpha_k \nabla f(x_k) - [x(t_k) - \alpha_k \nabla f(x(t_k))] \|~+ \label{local_b} \\[2mm] & ~ \| x(t_k) - \alpha_k \nabla f(x(t_k)) - x(t_{k+1}) \| \label{local_c} \\[2mm]
        \leqslant & ~ \|x_k - x(t_k)\| + \alpha_k \|\nabla f(x_k) - \nabla f(x(t_k))\| ~+ \label{local_d} \\[2mm]
        & ~ ML\alpha_k^2/2 \label{local_e} \\[2mm]
        \leqslant & ~ (1+\alpha_k M)\|x_k - x(t_k)\| + ML\alpha_k^2/2. \label{local_f}
    \end{align}
\end{subequations}
The term in \eqref{local_c} is equal to the local truncation error $\|x(t_{k+1})  - x(t_k) - x'(t_k)(t_{k+1}-t_k) \|$, and can hence be bounded above using \eqref{eq:local_error}. In the second term of \eqref{local_d}, we invoke a Lipschitz constant of $\nabla f$ on the convex hull of $B(X_0,\sigma_T(X_0)+1)$. Indeed, by the induction hypothesis and $\epsilon < 1$, $x_k$ and $x(t_k)$ belong to $B(X_0,\sigma_T(X_0)+\epsilon)$. Hence 
\begin{subequations}
    \begin{align}
        \|x_{K+1} - x(t_{K+1})\| \leqslant &~ \prod_{k=0}^K (1+\alpha_kM)\|x_0-x(t_0)\|~+ \label{eq:global_a}\\
        &~ \sum_{k=0}^K \frac{ML\alpha_k^2}{2} \prod_{l=k+1}^{K} (1+\alpha_lM)\label{eq:global_b}\\
        \leqslant &~ \prod_{l=0}^{K} (1+\alpha_lM) \sum_{k=0}^K \frac{ML\alpha_k^2}{2}\label{eq:global_c}\\
        \leqslant &~ \left(1+\frac{M}{K+1}\sum_{k=0}^K \alpha_k\right)^{K+1} \sum_{k=0}^K \frac{ML\bar{\alpha}\alpha_k}{2}\label{eq:global_d}\\
        \leqslant &~ \left(1+\frac{MT}{K+1}\right)^{K+1} \frac{ML\bar{\alpha}T}{2}\label{eq:global_e}\\
        \leqslant &~~ \bar{\alpha} LMTe^{MT}/2\label{eq:global_f}\\
        = &~~ \epsilon.\label{eq:global_g}
    \end{align}
\end{subequations}
The term in \eqref{eq:global_a} is equal to zero because $x_0 = x(t_0)$. By convention, we set the product in \eqref{eq:global_b} to be equal to one if the index set for $l$ is empty. We bound the partial products ranging from $k+1$ to $K$ inside the summation of \eqref{eq:global_b} by the full product ranging from $0$ to $K$ in order to obtain \eqref{eq:global_c}. We then use the inequality of arithmetic and geometric means and $\alpha_k\leqslant\bar{\alpha}$ in order to obtain \eqref{eq:global_d}. In order to prove the induction step, we assume that $\alpha_0+\cdots+\alpha_K \leqslant T$, hence \eqref{eq:global_e}. \eqref{eq:global_f} follows from $\ln(1+x) \leqslant x$ for all $x>0$. Finally, \eqref{eq:global_g} holds because $\bar{\alpha} = 2\epsilon e^{-MT}/(LMT)$.
\end{proof}

