\section{Proof of Lemma \ref{lemma:uniform_length}}
\label{sec:Proof of Lemma lemma:uniform_length}

Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz definable function with bounded continuous subgradient trajectories. Let $X_0$ be a bounded subset of $\mathbb{R}^n$. We will show that $\sigma(X_0) < \infty$ where 
\begin{subequations}
\label{eq:sup_trajectory}
\begin{align}
    \sigma(X_0) := & \sup\limits_{x \in \mathcal{A}(\mathbb{R}_+,\mathbb{R}^n)} ~~ \int_0^{\infty} \|x'(t)\|dt \\
  & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x'(t) \in - \partial f(x(t)), ~\mathrm{for~a.e.}~ t > 0,\\[3mm] x(0) \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}
Without loss of generality, we may assume that $X_0\neq \emptyset$. By Propositions \ref{prop:existence_trajectory} and \ref{prop:bounded_global}, the feasible set of \eqref{eq:sup_trajectory} is thus non-empty and $\sigma(X_0)>-\infty$.

We first consider the case with finite time horizon $T\geqslant 0$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Notice that $\sigma_T(X_0) \leqslant \sqrt{T(\sup_{X_0} f - m(f))}$ where $m(f)$ is the smallest critical value of $f$ and 
\begin{subequations}
\label{eq:sup_trajectory_T}
\begin{align}
    \sigma_T(X_0) := & \sup\limits_{x \in \mathcal{A}(\mathbb{R}_+,\mathbb{R}^n)} ~~ \int_0^T \|x'(t)\|dt \\
  & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x'(t) \in - \partial f(x(t)), ~\mathrm{for~a.e.}~ t > 0,\\[3mm] x(0) \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}
Indeed, by the Cauchy-Schwarz inequality and Propositions \ref{prop:chain_rule} and \ref{prop:length_continuous}, for any feasible point $x(\cdot)$ of \eqref{eq:sup_trajectory_T} we have
\begin{subequations}
\begin{align}
    \int_0^T \|x'(t)\|dt & \leqslant \sqrt{T} \sqrt{ \int_0^T \|x'(t)\|^2 dt} \\
    & \leqslant \sqrt{T} \sqrt{ \int_0^{\infty} \|x'(t)\|^2 dt} \\
    & = \sqrt{T} \sqrt{f(x(0)) - f\left(\lim_{t\rightarrow\infty} x(t)\right)} \\
    & \leqslant \sqrt{T\left(\sup_{X_0} f - m(f)\right)}. \label{eq:finite_time}
\end{align}
\end{subequations}

We next treat the case with infinite time horizon. Consider a sequence of feasible points $x_0(\cdot), x_1(\cdot), x_2(\cdot), \ldots$ of \eqref{eq:sup_trajectory}  such that $\int_0^{\infty} \|x_k'(t)\|dt$ converges to $\sigma(X_0)$. We proceed to show that the sequence is equicontinuous. Let $\epsilon>0$ and $t\geqslant 0$. Consider problem \eqref{eq:sup_trajectory_T} with finite time horizon $T:=t+\epsilon$. Since $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ are feasible points of \eqref{eq:sup_trajectory_T}, for all $s \in [0,T]$ and $k=0,1,2,\ldots$ we have
\begin{subequations}
    \begin{align}
        \|x_k(s)\| & \leqslant \|x_k(s) - x_k(0) \| + \|x_k(0)\| \label{upper_0} \\ & \leqslant \int_0^s \|x_k'(\tau)\|d\tau + \|x_k(0)\| \label{upper_1} \\
        & \leqslant \sigma_T(X_0) + \sup_{x_0 \in X_0} \|x_0\|. \label{upper_2}
    \end{align}
\end{subequations}
All the trajectories $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ hence belong to a common ball centered at the origin up to time $T$. Let $L>0$ be a Lipschitz constant of $f$ on that ball. As a result, for all $s \in [t-\delta,t+\delta]$ with $\delta:=\epsilon/(2L)$ and for all $k\in \mathbb{N}$, we have
\begin{equation*}
    \|x_k(t)-x_k(s)\| = \left\| \int_{s}^t x'_k(\tau)d\tau \right\| \leqslant \int_{t-\delta}^{t+\delta} \|x'_k(\tau)\| d\tau \leqslant 2\delta L = \epsilon,
\end{equation*}
It follows that $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ is equicontinuous on $\mathbb{R}_+$. In addition, \eqref{upper_0}-\eqref{upper_2} imply that, for all $t\geqslant 0$, the sequence $x_0(t),x_1(t),x_2(t),\ldots$ is bounded. The Arzel\`a-Ascoli theorem \cite[Theorem 1 p. 13]{aubin1984differential} implies that there exists a subsequence (again denoted $x_k(\cdot)$) converging uniformly over compact intervals to a continuous function $x:\mathbb{R}_+\rightarrow\mathbb{R}^n$. 

We next show that $x(\cdot)$ is a continuous subgradient trajectory of $f$. Let $T\geqslant 0$. By virtue of \eqref{upper_0}-\eqref{upper_2} and local Lipschitz continuity of $f$, the restrictions of $x'_0(\cdot),x'_1(\cdot),x'_2(\cdot),\ldots$ to $[0,T]$ lie in a ball of the dual space of $L^1([0,T],\mathbb{R}^n)$, namely $L^{\infty}([0,T],\mathbb{R}^n)$. By the Banach-Alaoglu theorem \cite[Theorem 3 p. 13]{aubin1984differential}, there exists a subsequence (again denoted $x_k'(\cdot)$) that converges weakly\textsuperscript{$\ast$} to a function $y(\cdot)$ in $L^{\infty}([0,T],\mathbb{R}^n)$. Together with $L^{\infty}([0,T],\mathbb{R}^n)\subset L^1([0,T],\mathbb{R}^n)$, we find that $x_k'(\cdot)$ converges weakly to $y(\cdot)$ in $L^1([0,T],\mathbb{R}^n)$. Since $x_k(t)-x_k(s) = \int_s^t x_k'(\tau)d\tau$ for all $0\leqslant s \leqslant t \leqslant T$, we have $x(t)-x(s) = \int_s^t y(\tau)d\tau$. As a result, $x'(t) = y(t)$ for almost every $t\in (0,T)$. According to \cite[Convergence Theorem p. 60]{aubin1984differential}, it follows that $x'(t) \in -\partial f(x(t))$ for almost every $t\in(0,T)$. As $T \geqslant 0$ was arbitrary, we have $x'(t) \in -\partial f(x(t))$ for almost every $t>0$.

% https://www.math.ucdavis.edu/~hunter/pdes/ch6A.pdf

Since $f$ is definable and has bounded continuous subgradient trajectories, by Proposition \ref{prop:length_continuous} $x(\cdot)$ has finite length and converges to a critical point $x^*$ of $f$. Let $\epsilon>0$ and let $m \in \mathbb{N}^*$ be the number of critical values of $f$ in $B(\overline{x(\mathbb{R}_+)},\epsilon)$. Let $\psi$ be a desingularizing function of $f$ on $B(\overline{x(\mathbb{R}_+)},\epsilon)$. Since $f$ is continuous, there exists $\delta \in (0,\epsilon/2)$ such that 
\begin{equation}
\label{eq:f_bound_continuous}
    f(x) - f(x^*) \leqslant m~\psi^{-1}\left(\frac{\epsilon}{4m}\right),~~~ \forall x\in B(x^*,\delta).
\end{equation}

Let $t^*\geqslant 0$ be such that $\|x(t)-x^*\| \leqslant \delta/2$ for all $t\geqslant t^*$. By the uniform convergence of $x_k(\cdot)$, we have that $\|x_k(t)-x(t)\|\leqslant \delta/2$ for all $t\in [0,t^*]$ for all $k$ large enough. Hence $\|x_k(t^*) - x^*\|\leqslant \|x_k(t^*)-x(t^*)\|+\|x(t^*)-x^*\| \leqslant \delta/2 + \delta/2 = \delta$. If $T_k := \inf\{ t \geqslant t^* : x_k(t) \notin \mathring{B}(x^*,\epsilon)\}<\infty$, then
\begin{subequations}
    \begin{align}
        2m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) & \leqslant 2m~ \psi^{-1}\left(\frac{\epsilon-\delta}{2m}\right) \label{eq:decrease_continuous_a} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{\|x_k(T_k)-x^*\| - \|x_k(t^*)-x^*\|}{2m}\right) \label{eq:decrease_continuous_b} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{\|x_k(T_k)-x_k(t^*)\|}{2m}\right) \label{eq:decrease_continuous_c} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{2m}\int_{t^*}^{T_k}\|x_k'(t)\|dt \right) \label{eq:decrease_continuous_d} \\
        & \leqslant f(x_k(t^*))-f(x_k(T_k)) \label{eq:decrease_continuous_e} \\[3mm]
        & \leqslant m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) + f(x^*) - f(x_k(T_k)). \label{eq:decrease_continuous_f}
    \end{align}
\end{subequations}
Above, \eqref{eq:decrease_continuous_a} through \eqref{eq:decrease_continuous_d} rely on the fact that $\psi^{-1}$ is increasing. \eqref{eq:decrease_continuous_a} is due to $\delta < \epsilon/2$. \eqref{eq:decrease_continuous_b} holds because $\|x_k(T_k)-x^*\|\geqslant \epsilon$ by continuity of $x_k(\cdot)$ and $x_k(t^*) \in B(x^*,\delta)$. \eqref{eq:decrease_continuous_c} is a consequence of the triangular inequality. \eqref{eq:decrease_continuous_d} holds because $x_k(\cdot)$ is absolutely continuous. \eqref{eq:decrease_continuous_e} is due to Proposition \ref{prop:length_continuous} and the fact that $x_k(t) \in B(x^*,\epsilon)$ for all $t \in [t^*,T_k]$ by continuity of $x_k(\cdot)$. Finally, \eqref{eq:decrease_continuous_f} is due to $x_k(t^*)\in B(x^*,\delta)$ and \eqref{eq:f_bound_continuous}. Since $x_k(t) \in B(\overline{x(\mathbb{R}_+)},\epsilon)$ for all $t\in [0,T_k]$ and $x_k(T_k)$ belongs to
\begin{equation*}
     X_1 := B(x^*,\epsilon) \bigcap \left\{ x \in \mathbb{R}^n : f(x) \leqslant f(x^*) - m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) \right\},
\end{equation*}
by Proposition \ref{prop:length_continuous} and the definition of $\sigma(\cdot)$ in \eqref{eq:sup_trajectory} we have 
    \begin{align*}
            \int_0^{\infty} \|x_k'(t)\|dt & = \int_{0}^{T_k} \|x_k'(t)\|dt + \int_{T_k}^{\infty} \|x_k'(t)\|dt \\
            & \leqslant 2m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(x^*,\epsilon)} f\right) \right) + \max\{0,\sigma(X_1)\}.
    \end{align*}
Note that the inequality still holds if $T_k = \infty$. By taking the limit, we get
\begin{equation*}
    \sigma(X_0) ~\leqslant~ 2m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(x^*,\epsilon)} f\right) \right) + \max\{0,\sigma(X_1)\}.
\end{equation*}

It now suffices to replace $X_0$ by $X_1$ and repeat the proof starting below \eqref{eq:finite_time}. A maximizing sequence $\bar{x}_k(\cdot)$ corresponding to $\sigma(X_1)$ converges to a continuous subgradient trajectory $\bar{x}(\cdot)$ whose initial point lies in the compact set $X_1$. If $X_1 \neq \emptyset$, then the critical value $f(\lim_{t\rightarrow\infty} \bar{x}(t))$ is less than or equal to $f(x^*) - m\psi^{-1}(\epsilon/(4m)) < f(x^*)$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Thus, it is eventually the case that one of the sets $X_0,X_1,\hdots$ is empty. We conclude that $\sigma(X_0)<\infty$ by the above recursive formula.

\section{Proof of Lemma \ref{lemma:uniform_length}}
\label{sec:Proof of Lemma lemma:uniform_length}

Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz definable function with bounded continuous subgradient trajectories. Let $X_0$ be a bounded subset of $\mathbb{R}^n$. We will show that $\sigma(X_0) < \infty$ where 
\begin{subequations}
\label{eq:sup_trajectory}
\begin{align}
    \sigma(X_0) := & \sup\limits_{x \in \mathcal{A}(\mathbb{R}_+,\mathbb{R}^n)} ~~ \int_0^{\infty} \|x'(t)\|dt \\
  & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x'(t) \in - \partial f(x(t)), ~\mathrm{for~a.e.}~ t > 0,\\[3mm] x(0) \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}
Without loss of generality, we may assume that $X_0\neq \emptyset$. By Propositions \ref{prop:existence_trajectory} and \ref{prop:bounded_global}, the feasible set of \eqref{eq:sup_trajectory} is thus non-empty and $\sigma(X_0)>-\infty$.

We first consider the case with finite time horizon $T\geqslant 0$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Notice that $\sigma_T(X_0) \leqslant \sqrt{T(\sup_{X_0} f - m(f))}$ where $m(f)$ is the smallest critical value of $f$ and 
\begin{subequations}
\label{eq:sup_trajectory_T}
\begin{align}
    \sigma_T(X_0) := & \sup\limits_{x \in \mathcal{A}(\mathbb{R}_+,\mathbb{R}^n)} ~~ \int_0^T \|x'(t)\|dt \\
  & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x'(t) \in - \partial f(x(t)), ~\mathrm{for~a.e.}~ t > 0,\\[3mm] x(0) \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}
Indeed, by the Cauchy-Schwarz inequality and Propositions \ref{prop:chain_rule} and \ref{prop:length_continuous}, for any feasible point $x(\cdot)$ of \eqref{eq:sup_trajectory_T} we have
\begin{subequations}
\begin{align}
    \int_0^T \|x'(t)\|dt & \leqslant \sqrt{T} \sqrt{ \int_0^T \|x'(t)\|^2 dt} \\
    & \leqslant \sqrt{T} \sqrt{ \int_0^{\infty} \|x'(t)\|^2 dt} \\
    & = \sqrt{T} \sqrt{f(x(0)) - f\left(\lim_{t\rightarrow\infty} x(t)\right)} \\
    & \leqslant \sqrt{T\left(\sup_{X_0} f - m(f)\right)}. \label{eq:finite_time}
\end{align}
\end{subequations}

We next treat the case with infinite time horizon. Consider a sequence of feasible points $x_0(\cdot), x_1(\cdot), x_2(\cdot), \ldots$ of \eqref{eq:sup_trajectory}  such that $\int_0^{\infty} \|x_k'(t)\|dt$ converges to $\sigma(X_0)$. We proceed to show that the sequence is equicontinuous. Let $\epsilon>0$ and $t\geqslant 0$. Consider problem \eqref{eq:sup_trajectory_T} with finite time horizon $T:=t+\epsilon$. Since $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ are feasible points of \eqref{eq:sup_trajectory_T}, for all $s \in [0,T]$ and $k=0,1,2,\ldots$ we have
\begin{subequations}
    \begin{align}
        \|x_k(s)\| & \leqslant \|x_k(s) - x_k(0) \| + \|x_k(0)\| \label{upper_0} \\ & \leqslant \int_0^s \|x_k'(\tau)\|d\tau + \|x_k(0)\| \label{upper_1} \\
        & \leqslant \sigma_T(X_0) + \sup_{x_0 \in X_0} \|x_0\|. \label{upper_2}
    \end{align}
\end{subequations}
All the trajectories $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ hence belong to a common ball centered at the origin up to time $T$. Let $L>0$ be a Lipschitz constant of $f$ on that ball. As a result, for all $s \in [t-\delta,t+\delta]$ with $\delta:=\epsilon/(2L)$ and for all $k\in \mathbb{N}$, we have
\begin{equation*}
    \|x_k(t)-x_k(s)\| = \left\| \int_{s}^t x'_k(\tau)d\tau \right\| \leqslant \int_{t-\delta}^{t+\delta} \|x'_k(\tau)\| d\tau \leqslant 2\delta L = \epsilon,
\end{equation*}
It follows that $x_0(\cdot),x_1(\cdot),x_2(\cdot),\ldots$ is equicontinuous on $\mathbb{R}_+$. In addition, \eqref{upper_0}-\eqref{upper_2} imply that, for all $t\geqslant 0$, the sequence $x_0(t),x_1(t),x_2(t),\ldots$ is bounded. The Arzel\`a-Ascoli theorem \cite[Theorem 1 p. 13]{aubin1984differential} implies that there exists a subsequence (again denoted $x_k(\cdot)$) converging uniformly over compact intervals to a continuous function $x:\mathbb{R}_+\rightarrow\mathbb{R}^n$.

Since $f$ is definable and has bounded continuous subgradient trajectories, by Proposition \ref{prop:length_continuous} $x(\cdot)$ has finite length and converges to a critical point $x^*$ of $f$. Let $\epsilon>0$ and let $m \in \mathbb{N}^*$ be the number of critical values of $f$ in $B(\overline{x(\mathbb{R}_+)},\epsilon)$. Let $\psi$ be a desingularizing function of $f$ on $B(\overline{x(\mathbb{R}_+)},\epsilon)$. Since $f$ is continuous, there exists $\delta \in (0,\epsilon/2)$ such that 
\begin{equation}
\label{eq:f_bound_continuous}
    f(x) - f(x^*) \leqslant m~\psi^{-1}\left(\frac{\epsilon}{4m}\right),~~~ \forall x\in B(x^*,\delta).
\end{equation}

Let $t^*\geqslant 0$ be such that $\|x(t)-x^*\| \leqslant \delta/2$ for all $t\geqslant t^*$. By the uniform convergence of $x_k(\cdot)$, we have that $\|x_k(t)-x(t)\|\leqslant \delta/2$ for all $t\in [0,t^*]$ for all $k$ large enough. Hence $\|x_k(t^*) - x^*\|\leqslant \|x_k(t^*)-x(t^*)\|+\|x(t^*)-x^*\| \leqslant \delta/2 + \delta/2 = \delta$. If $T_k := \inf\{ t \geqslant t^* : x_k(t) \notin \mathring{B}(x^*,\epsilon)\}<\infty$, then
\begin{subequations}
    \begin{align}
        2m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) & \leqslant 2m~ \psi^{-1}\left(\frac{\epsilon-\delta}{2m}\right) \label{eq:decrease_continuous_a} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{\|x_k(T_k)-x^*\| - \|x_k(t^*)-x^*\|}{2m}\right) \label{eq:decrease_continuous_b} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{\|x_k(T_k)-x_k(t^*)\|}{2m}\right) \label{eq:decrease_continuous_c} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{2m}\int_{t^*}^{T_k}\|x_k'(t)\|dt \right) \label{eq:decrease_continuous_d} \\
        & \leqslant f(x_k(t^*))-f(x_k(T_k)) \label{eq:decrease_continuous_e} \\[3mm]
        & \leqslant m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) + f(x^*) - f(x_k(T_k)). \label{eq:decrease_continuous_f}
    \end{align}
\end{subequations}
Above, \eqref{eq:decrease_continuous_a} through \eqref{eq:decrease_continuous_d} rely on the fact that $\psi^{-1}$ is increasing. \eqref{eq:decrease_continuous_a} is due to $\delta < \epsilon/2$. \eqref{eq:decrease_continuous_b} holds because $\|x_k(T_k)-x^*\|\geqslant \epsilon$ by continuity of $x_k(\cdot)$ and $x_k(t^*) \in B(x^*,\delta)$. \eqref{eq:decrease_continuous_c} is a consequence of the triangular inequality. \eqref{eq:decrease_continuous_d} holds because $x_k(\cdot)$ is absolutely continuous. \eqref{eq:decrease_continuous_e} is due to Proposition \ref{prop:length_continuous} and the fact that $x_k(t) \in B(x^*,\epsilon)$ for all $t \in [t^*,T_k]$ by continuity of $x_k(\cdot)$. Finally, \eqref{eq:decrease_continuous_f} is due to $x_k(t^*)\in B(x^*,\delta)$ and \eqref{eq:f_bound_continuous}. Since $x_k(t) \in B(\overline{x(\mathbb{R}_+)},\epsilon)$ for all $t\in [0,T_k]$ and $x_k(T_k)$ belongs to
\begin{equation*}
     X_1 := B(x^*,\epsilon) \bigcap \left\{ x \in \mathbb{R}^n : f(x) \leqslant f(x^*) - m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) \right\},
\end{equation*}

by Proposition \ref{prop:length_continuous} and the definition of $\sigma(\cdot)$ in \eqref{eq:sup_trajectory} we have 
    \begin{align*}
            \int_0^{\infty} \|x_k'(t)\|dt & = \int_{0}^{T_k} \|x_k'(t)\|dt + \int_{T_k}^{\infty} \|x_k'(t)\|dt \\
            & \leqslant 2m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(x^*,\epsilon)} f\right) \right) + \max\{0,\sigma(X_1)\}.
    \end{align*}
Note that the inequality still holds if $T_k = \infty$. By taking the limit, we get
\begin{equation*}
    \sigma(X_0) ~\leqslant~ 2m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(x^*,\epsilon)} f\right) \right) + \max\{0,\sigma(X_1)\}.
\end{equation*}

\section{Proof of Theorem \ref{thm:convergence}}
\label{sec:Proof of Theorem thm:convergence}

($1\Longrightarrow 2$) We prove the contrapositive. Assume that there exists $0< T \leqslant \infty$ and a differentiable function $x:[0,T)\rightarrow\mathbb{R}^n$ such that
\begin{equation*}
    x'(t) = -\nabla f(x(t)), ~~~ \forall t \in (0,T),
\end{equation*}
for which, for all $c>0$, there exists $t\in [0,T)$ such that $\|x(t)\| > c$. Let $x_0 := x(0)$. Let $\bar{\alpha}$ and $c$ be some positive constants. Let $\tilde{t} \in (0,T)$ be such that $\|x(\tilde{t})\| \geqslant c+2$. By Proposition \ref{prop:tracking} and Remark \ref{rem:tracking}, there exists $\tilde{\alpha}\in (0,\bar{\alpha}]$ such that for all $\alpha \in (0,\tilde{\alpha}]$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by $x_{k+1} = x_k -\alpha \nabla f(x_k)$ for all $k \in \mathbb{N}$ satisfies $\|x_k-x(k\alpha)\| \leqslant 1/2$ for all $k\in \{0,\hdots, \lfloor \tilde{t}/\alpha \rfloor \}$. We use the notation $\lfloor t \rfloor$ to denote the floor of a real number $t$ which is the unique integer such that $\lfloor t \rfloor \leqslant t < \lfloor t \rfloor + 1$. If $\tilde{k} = \lfloor \tilde{t}/\alpha \rfloor$, then $\|x_{\tilde{k}} - x(\tilde{t})\| \leqslant \|x_{\tilde{k}}-x(\tilde{k}\alpha)\|+\|x(\tilde{k}\alpha)-x(\tilde{t})\| \leqslant 1/2 + \tilde{L}| \tilde{k}\alpha-\tilde{t}| \leqslant 1/2 + \tilde{L}\alpha$ where $\tilde{L}>0$ is a Lipschitz constant of $f$ on the convex hull of $x([\tilde{t}-\tilde{\alpha},\tilde{t}])$. Let $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$ be the constant sequence equal to $\min \{\tilde{\alpha}, 1/(2\tilde{L})\}$ and consider the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by $x_{k+1} = x_k -\alpha_k \nabla f(x_k)$ for all $k \in \mathbb{N}$. By the triangular inequality, we have $\|x_{\tilde{k}}\| \geqslant \|x(\tilde{t})\| - \|x_{\tilde{k}}-x(\tilde{t})\| \geqslant c+2 - 1/2 - 1/2>c$ where $\tilde{k} := \lfloor \tilde{t}/\alpha \rfloor$.

($2 \Longrightarrow 3$) Let $X_0$ be a bounded subset of $\mathbb{R}^n$. We will show that there exists $\bar{\alpha}>0$ such that $\sigma(X_0,\bar{\alpha})<\infty$ where
\begin{subequations}
\label{eq:sup_discrete_X_0}
\begin{align}
    \sigma(X_0,\bar{\alpha}) := & \sup\limits_{\tiny \begin{array}{c}x \in (\mathbb{R}^n)^{\mathbb{N}}\\ \alpha \in (0,\bar{\alpha}]^\mathbb{N} \end{array}} ~~ \sum\limits_{k=0}^{\infty} \|x_{k+1}-x_k\| \\
   & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x_{k+1} = x_k - \alpha_k \nabla f(x_k), ~ \forall k\in \mathbb{N},\\[2mm] x_0 \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}

Let $\Phi:\mathbb{R}_+ \times \mathbb{R}^n \rightarrow \mathbb{R}^n$ be the gradient flow of $f$ defined for all $(t,x_0) \in \mathbb{R}_+ \times \mathbb{R}^n$ by $\Phi(t,x_0) := x(t)$ where $x(\cdot)$ is the unique continuous gradient trajectory of $f$ initialized at $x_0$. Uniqueness follows from the Picard–Lindel{\"o}f theorem \cite[Theorem 3.1 p. 12]{coddington1955theory}. Let $C$ be the set of critical points of $f$ in $\overline{\Phi(\mathbb{R}_+,X_0)}$. If $X_0 \subset C$, then we have $\sigma(X_0,\bar{\alpha}) \leqslant 0$ for all $\bar{\alpha}>0$ and there is nothing left to prove. Otherwise, since $C$ is closed by \cite[2.1.5 Proposition p. 29]{clarke1990}, there exists $\epsilon>0$ be such that $X_0\setminus \mathring{B}(C,\epsilon/6) \neq \emptyset$ where $\mathring{B}(C,\epsilon/6) := C + \mathring{B}(0,\epsilon/6)$. It is safe to assume this from now on.

Let $\psi$ be a desingularizing function of $f$ on $\mathring{B}(\overline{\Phi}_0,\epsilon)$, where we use the shorthand $\Phi_0 := \Phi(\mathbb{R}_+,X_0)$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Let $m \in \mathbb{N}$ be the number of critical values of $f$ in $B(\overline{\Phi}_0,\epsilon)$. Note that $m \geqslant 1$ due to Proposition \ref{prop:length_continuous} and the fact that $X_0 \neq \emptyset$. Since $f$ is continuous and $C$ is compact by Lemma \ref{lemma:uniform_length}, there exists $\delta \in (0,\epsilon/2)$ such that  
\begin{equation}
    \label{eq:f_bound_discrete}
    f(x) - \max_{C} f \leqslant m~ \psi^{-1}\left(\frac{\epsilon}{40m}\right),~~~ \forall x\in B(C,\delta).
\end{equation}
Note that $\mathring{B}(\overline{\Phi}_0,\epsilon)$ is bounded due to Lemma \ref{lemma:uniform_length}. Let $L>0$ be a Lipschitz constant of $f$ on the convex hull of $\mathring{B}(\overline{\Phi}_0,\epsilon)$. By Proposition \ref{prop:length_discrete}, there exists $\alpha_\delta \in (0,\delta/(5mL)]$ such that, for all $K \in \mathbb{N}^*$, $\alpha_0,\hdots,\alpha_{K-1} \in (0,\alpha_\delta]$, and $(x_0,\hdots,x_K) \in \mathring{B}(\overline{\Phi}_0,\epsilon) \times \cdots \times \mathring{B}(\overline{\Phi}_0,\epsilon) \times \mathbb{R}^n$ such that $x_{k+1} = x_k - \alpha_k \nabla f(x_k)$ for $k = 0,\hdots,K-1$, we have
\begin{equation}
\label{eq:length_discrete_K}
    \frac{1}{4m}\sum_{k=0}^{K-1}\|x_{k+1}-x_k\| ~\leqslant~ \psi\left(\frac{f(x_0)-f(x_{K-1})}{2m}\right) + \frac{L}{2}\max_{k=0,\hdots,K-1} \alpha_k.
\end{equation}

Since $\nabla f$ is continuous, its norm attains its infimum $\nu$ on the nonempty compact set $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$. 
It is nonempty because $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3) \supset X_0\setminus \mathring{B}(C,\epsilon/6) \neq \emptyset$ and $\delta < \epsilon/2$.
If $\nu=0$, then there exists $x^* \in \overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$ such that $\|\nabla f(x^*)\| = 0$. Then $x^*\in C \setminus \mathring{B}(C,\delta/3)$, which is a contradiction. We thus have $\nu>0$. Hence we may define $T := 2\sigma(X_0)/\nu$ where $\sigma(X_0)$ is defined in \eqref{eq:sup_trajectory} and is finite by Lemma \ref{lemma:uniform_length}. Note that $\sigma(X_0)>0$ and thus $T>0$ because $X_0\not\subset C$. By Proposition \ref{prop:tracking}, there exists $\bar{\alpha} \in (0,\alpha_\delta]$ such that for any feasible point $((x_k)_{k\in \mathbb{N}} , (\alpha_k)_{k\in\mathbb{N}})$ of \eqref{eq:sup_discrete_X_0},
the continuous gradient trajectory $x:\mathbb{R}_+\rightarrow \mathbb{R}^n$ of $f$ initialized at $x_0$ satisfies
\begin{equation}
\label{eq:tracking_T}
   \forall k\in \mathbb{N}^*,~~~ \alpha_0+\cdots+\alpha_{k-1} \leqslant T ~~~\Longrightarrow~~~ \|x_k - x(\alpha_0+\cdots+\alpha_{k-1})\| \leqslant \frac{\delta}{3}.
\end{equation}
Now suppose that $\|x'(t)\| \geqslant 2\sigma(X_0)/T$ for all $t\in (0,T)$. Then we obtain the following contradiction
\begin{equation*}
     \sigma(X_0) < T \frac{2\sigma(X_0)}{T} \leqslant \int_0^{T} \|x'(t)\|dt \leqslant \int_0^{\infty} \|x'(t)\|dt \leqslant \sigma(X_0).
\end{equation*}
Hence, there exists $t^* \in (0,T)$ such that $\|x'(t^*)\| = \|\nabla f(x(t^*))\| < 2\sigma(X_0)/T = 2\sigma(X_0)/(2\sigma(X_0)/\nu) = \nu$. Since  $x(t^*) \in \Phi(\mathbb{R}_+,X_0) \subset \overline{\Phi}_0$ and the infimum of the norm of $\nabla f$ on $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$ is equal to $\nu$, it must be that $x(t^*) \in \mathring{B}(C,\delta/3)$. Hence there exists $x^* \in C$ such that $\|x(t^*)-x^*\|\leqslant \delta/3$. 

If $\sum_{k=0}^{\infty} \alpha_k \leqslant T$, then by \eqref{eq:tracking_T} we have $x_k \in B(\overline{\Phi}_0,\delta/3)$ for all $k \in \mathbb{N}$. Otherwise, since $\alpha_k \leqslant \bar{\alpha} \leqslant \alpha_\delta \leqslant \delta/(5mL) \leqslant \delta/(3L)$ for all $k \in \mathbb{N}$, there exists $k^* \in \mathbb{N}$ such that $t_{k^*} := \sum_{k=0}^{k^*-1} \alpha_k \in [ t^* - \delta/(3L) , t^*]$, where $\sum_{k=0}^{k^*-1} \alpha_k = 0$ if $k^* = 0$. Thus $\|x_{k^*}-x^*\| \leqslant \|x_{k^*}-x(t_{k^*})\| + \|x(t_{k^*}) - x(t^*)\| + \|x(t^*)-x^*\| \leqslant \delta/3 + L | t_{k^*}-t^* | + \delta/3 \leqslant \delta/3+\delta/3+\delta/3 = \delta$.
If $K := \inf\{ k \geqslant k^* : x_k \notin \mathring{B}(C,\epsilon)\}<\infty$, then
\begin{subequations}
    \begin{align}
        2m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) & = 2m~ \psi^{-1}\left(\frac{1}{8m} \epsilon - \frac{L}{2}\frac{\epsilon}{5mL} \right) \label{eq:decrease_discrete_a} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m}(\epsilon-\delta) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_b} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \left(\|x_K-x^*\|-\|x_{k^*}-x^*\|\right) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_c} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \|x_K-x_{k^*}\| - \frac{L\bar{\alpha}}{2} \right) \label{eq:decrease_discrete_d} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m}\sum_{k=k^*}^{K-1} \|x_{k+1}-x_k\| - \frac{L}{2}\max_{k=0,\hdots,K-1} \alpha_k \right) \label{eq:decrease_discrete_e} \\
        & \leqslant f(x_{k^*}) - f(x_{K-1}) \label{eq:decrease_discrete_f} \\
        & \leqslant m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) + \max_C f - f(x_{K-1}). \label{eq:decrease_discrete_g}
    \end{align}
\end{subequations}
Above, the arguments of $\psi^{-1}$ in \eqref{eq:decrease_discrete_a} are equal. \eqref{eq:decrease_discrete_b} through \eqref{eq:decrease_discrete_e} rely on the fact that $\psi^{-1}$ is an increasing function. \eqref{eq:decrease_discrete_b} is due to $\delta<\epsilon/2$. \eqref{eq:decrease_discrete_c} holds because $x_K \notin \mathring{B}(C,\epsilon)$, $x^* \in C$, and $x_{k^*} \in B(x^*,\delta)$. \eqref{eq:decrease_discrete_d} and \eqref{eq:decrease_discrete_e} are consequences of the triangular inequality. \eqref{eq:decrease_discrete_f} is due to the length formula \eqref{eq:length_discrete_K} and the fact that $x_{k^*},\hdots,x_{K-1} \in \mathring{B}(C,\epsilon) \subset \mathring{B}(\overline{\Phi}_0,\epsilon)$. Finally, \eqref{eq:decrease_discrete_g} is due to $x_{k^*}\in B(C,\delta)$ and \eqref{eq:f_bound_discrete}. We remark that $K\geqslant k^*+2$ since $\|x_{k^*+1}-x^*\| \leqslant \|x_{k^*+1}-x_{k^*}\| +\|x_{k^*}-x^*\| \leqslant \alpha_{k^*}\|\nabla f(x_{k^*})\|+\delta \leqslant (\delta/(5mL))L+\delta < \epsilon$. Since $x_0,\hdots,x_{K-2} \in \mathring{B}(\overline{\Phi}_0,\epsilon)$ and $x_{K-1}$ belongs to 
\begin{equation*}
    X_1 := B(C,\epsilon) \bigcap \left\{ x \in \mathbb{R}^n : f(x) \leqslant \max_{C} f - m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) \right\},    
\end{equation*}
by the length formula \eqref{eq:length_discrete_K} and the definition of $\sigma(\cdot,\cdot)$ in \eqref{eq:sup_discrete_X_0} we have
    \begin{align*}
            \sum_{k=0}^\infty \|x_{k+1}-x_k\| & = \sum_{k=0}^{K-2} \|x_{k+1}-x_k\| + \sum_{k=K-1}^\infty \|x_{k+1}-x_k\| \\
            & \leqslant 4m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(\overline{\Phi}_0,\epsilon)} f\right) \right) + 2mL\bar{\alpha} + \max\{0,\sigma(X_1,\bar{\alpha})\}.
    \end{align*}
Note that the inequality still holds if $K = \infty$ or $\sum_{k=0}^{\infty} \alpha_k \leqslant T$. Hence
\begin{equation*}
    \sigma(X_0,\bar{\alpha}) ~\leqslant~ 4m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(\overline{\Phi}_0,\epsilon)} f\right) \right) + 2mL\bar{\alpha} + \max\{0,\sigma(X_1,\bar{\alpha})\}.
\end{equation*}

It now suffices to replace $X_0$ by $X_1$ and repeat the proof starting below \eqref{eq:sup_discrete_X_0}. Since $f(\Phi(t,x_1)) \leqslant f(\Phi(0,x_1)) \leqslant \max_{C} f - m\psi^{-1}(\epsilon/(40m))< \max_{C} f$ for all $t\geqslant 0$ and $x_1\in X_1$, the maximal critical value of $f$ in $\overline{\Phi(\mathbb{R}_+,X_1)}$ is less than the maximal critical value of $f$ in $\overline{\Phi(\mathbb{R}_+,X_0)}$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Thus, it is eventually the case that one of the sets $X_0,X_1,\hdots$ is empty. In order to conclude, one simply needs to choose an upper bound on the step sizes $\hat{\alpha}$ corresponding to $X_1$ that is less than or equal to the upper bound $\bar{\alpha}$ used for $X_0$. $\sigma(X_0,\cdot)$ is finite when evaluated at the last upper bound thus obtained. Indeed, the above recursive formula still holds if we replace $\bar{\alpha}$ by any $\alpha \in (0,\bar{\alpha}]$. In particular, we may take $\alpha := \hat{\alpha}$.

($3 \Longrightarrow 1$) Obvious.\\

($1\Longrightarrow 2$) We prove the contrapositive. Assume that there exists $0< T \leqslant \infty$ and a differentiable function $x:[0,T)\rightarrow\mathbb{R}^n$ such that
\begin{equation*}
    x'(t) = -\nabla f(x(t)), ~~~ \forall t \in (0,T),
\end{equation*}
for which, for all $c>0$, there exists $t\in [0,T)$ such that $\|x(t)\| > c$. Let $x_0 := x(0)$. Let $\bar{\alpha}$ and $c$ be some positive constants. Let $\tilde{t} \in (0,T)$ be such that $\|x(\tilde{t})\| \geqslant c+2$. By Proposition \ref{prop:tracking} and Remark \ref{rem:tracking}, there exists $\tilde{\alpha}\in (0,\bar{\alpha}]$ such that for all $\alpha \in (0,\tilde{\alpha}]$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by $x_{k+1} = x_k -\alpha \nabla f(x_k)$ for all $k \in \mathbb{N}$ satisfies $\|x_k-x(k\alpha)\| \leqslant 1/2$ for all $k\in \{0,\hdots, \lfloor \tilde{t}/\alpha \rfloor \}$. We use the notation $\lfloor t \rfloor$ to denote the floor of a real number $t$ which is the unique integer such that $\lfloor t \rfloor \leqslant t < \lfloor t \rfloor + 1$. If $\tilde{k} = \lfloor \tilde{t}/\alpha \rfloor$, then $\|x_{\tilde{k}} - x(\tilde{t})\| \leqslant \|x_{\tilde{k}}-x(\tilde{k}\alpha)\|+\|x(\tilde{k}\alpha)-x(\tilde{t})\| \leqslant 1/2 + \tilde{L}| \tilde{k}\alpha-\tilde{t}| \leqslant 1/2 + \tilde{L}\alpha$ where $\tilde{L}>0$ is a Lipschitz constant of $f$ on the convex hull of $x([\tilde{t}-\tilde{\alpha},\tilde{t}])$. Let $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$ be the constant sequence equal to $\min \{\tilde{\alpha}, 1/(2\tilde{L})\}$ and consider the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by $x_{k+1} = x_k -\alpha_k \nabla f(x_k)$ for all $k \in \mathbb{N}$. By the triangular inequality, we have $\|x_{\tilde{k}}\| \geqslant \|x(\tilde{t})\| - \|x_{\tilde{k}}-x(\tilde{t})\| \geqslant c+2 - 1/2 - 1/2>c$ where $\tilde{k} := \lfloor \tilde{t}/\alpha \rfloor$.

($2 \Longrightarrow 3$) Let $X_0$ be a bounded subset of $\mathbb{R}^n$. We will show that there exists $\bar{\alpha}>0$ such that $\sigma(X_0,\bar{\alpha})<\infty$ where
\begin{subequations}
\label{eq:sup_discrete_X_0}
\begin{align}
    \sigma(X_0,\bar{\alpha}) := & \sup\limits_{\tiny \begin{array}{c}x \in (\mathbb{R}^n)^{\mathbb{N}}\\ \alpha \in (0,\bar{\alpha}]^\mathbb{N} \end{array}} ~~ \sum\limits_{k=0}^{\infty} \|x_{k+1}-x_k\| \\
   & ~~ \mathrm{subject~to} ~~~ 
\left\{ 
\begin{array}{l}
x_{k+1} = x_k - \alpha_k \nabla f(x_k), ~ \forall k\in \mathbb{N},\\[2mm] x_0 \in X_0.
\end{array}
\right.
\end{align}
\end{subequations}

Let $\Phi:\mathbb{R}_+ \times \mathbb{R}^n \rightarrow \mathbb{R}^n$ be the gradient flow of $f$ defined for all $(t,x_0) \in \mathbb{R}_+ \times \mathbb{R}^n$ by $\Phi(t,x_0) := x(t)$ where $x(\cdot)$ is the unique continuous gradient trajectory of $f$ initialized at $x_0$. Uniqueness follows from the Picard–Lindel{\"o}f theorem \cite[Theorem 3.1 p. 12]{coddington1955theory}. Let $C$ be the set of critical points of $f$ in $\overline{\Phi(\mathbb{R}_+,X_0)}$. If $X_0 \subset C$, then we have $\sigma(X_0,\bar{\alpha}) \leqslant 0$ for all $\bar{\alpha}>0$ and there is nothing left to prove. Otherwise, since $C$ is closed by \cite[2.1.5 Proposition p. 29]{clarke1990}, there exists $\epsilon>0$ be such that $X_0\setminus \mathring{B}(C,\epsilon/6) \neq \emptyset$ where $\mathring{B}(C,\epsilon/6) := C + \mathring{B}(0,\epsilon/6)$. It is safe to assume this from now on.

Let $\psi$ be a desingularizing function of $f$ on $\mathring{B}(\overline{\Phi}_0,\epsilon)$, where we use the shorthand $\Phi_0 := \Phi(\mathbb{R}_+,X_0)$. By the definable Morse-Sard theorem \cite[Corollary 9]{bolte2007clarke}, $f$ has finitely many critical values. Let $m \in \mathbb{N}$ be the number of critical values of $f$ in $B(\overline{\Phi}_0,\epsilon)$. Note that $m \geqslant 1$ due to Proposition \ref{prop:length_continuous} and the fact that $X_0 \neq \emptyset$. Since $f$ is continuous and $C$ is compact by Lemma \ref{lemma:uniform_length}, there exists $\delta \in (0,\epsilon/2)$ such that  
\begin{equation}
    \label{eq:f_bound_discrete}
    f(x) - \max_{C} f \leqslant m~ \psi^{-1}\left(\frac{\epsilon}{40m}\right),~~~ \forall x\in B(C,\delta).
\end{equation}
Note that $\mathring{B}(\overline{\Phi}_0,\epsilon)$ is bounded due to Lemma \ref{lemma:uniform_length}. Let $L>0$ be a Lipschitz constant of $f$ on the convex hull of $\mathring{B}(\overline{\Phi}_0,\epsilon)$. By Proposition \ref{prop:length_discrete}, there exists $\alpha_\delta \in (0,\delta/(5mL)]$ such that, for all $K \in \mathbb{N}^*$, $\alpha_0,\hdots,\alpha_{K-1} \in (0,\alpha_\delta]$, and $(x_0,\hdots,x_K) \in \mathring{B}(\overline{\Phi}_0,\epsilon) \times \cdots \times \mathring{B}(\overline{\Phi}_0,\epsilon) \times \mathbb{R}^n$ such that $x_{k+1} = x_k - \alpha_k \nabla f(x_k)$ for $k = 0,\hdots,K-1$, we have
\begin{equation}
\label{eq:length_discrete_K}
    \frac{1}{4m}\sum_{k=0}^{K-1}\|x_{k+1}-x_k\| ~\leqslant~ \psi\left(\frac{f(x_0)-f(x_{K-1})}{2m}\right) + \frac{L}{2}\max_{k=0,\hdots,K-1} \alpha_k.
\end{equation}

Since $\nabla f$ is continuous, its norm attains its infimum $\nu$ on the nonempty compact set $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$. 
It is nonempty because $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3) \supset X_0\setminus \mathring{B}(C,\epsilon/6) \neq \emptyset$ and $\delta < \epsilon/2$.
If $\nu=0$, then there exists $x^* \in \overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$ such that $\|\nabla f(x^*)\| = 0$. Then $x^*\in C \setminus \mathring{B}(C,\delta/3)$, which is a contradiction. We thus have $\nu>0$. Hence we may define $T := 2\sigma(X_0)/\nu$ where $\sigma(X_0)$ is defined in \eqref{eq:sup_trajectory} and is finite by Lemma \ref{lemma:uniform_length}. Note that $\sigma(X_0)>0$ and thus $T>0$ because $X_0\not\subset C$. By Proposition \ref{prop:tracking}, there exists $\bar{\alpha} \in (0,\alpha_\delta]$ such that for any feasible point $((x_k)_{k\in \mathbb{N}} , (\alpha_k)_{k\in\mathbb{N}})$ of \eqref{eq:sup_discrete_X_0},
the continuous gradient trajectory $x:\mathbb{R}_+\rightarrow \mathbb{R}^n$ of $f$ initialized at $x_0$ satisfies
\begin{equation}
\label{eq:tracking_T}
   \forall k\in \mathbb{N}^*,~~~ \alpha_0+\cdots+\alpha_{k-1} \leqslant T ~~~\Longrightarrow~~~ \|x_k - x(\alpha_0+\cdots+\alpha_{k-1})\| \leqslant \frac{\delta}{3}.
\end{equation}

Now suppose that $\|x'(t)\| \geqslant 2\sigma(X_0)/T$ for all $t\in (0,T)$. Then we obtain the following contradiction
\begin{equation*}
     \sigma(X_0) < T \frac{2\sigma(X_0)}{T} \leqslant \int_0^{T} \|x'(t)\|dt \leqslant \int_0^{\infty} \|x'(t)\|dt \leqslant \sigma(X_0).
\end{equation*}
Hence, there exists $t^* \in (0,T)$ such that $\|x'(t^*)\| = \|\nabla f(x(t^*))\| < 2\sigma(X_0)/T = 2\sigma(X_0)/(2\sigma(X_0)/\nu) = \nu$. Since  $x(t^*) \in \Phi(\mathbb{R}_+,X_0) \subset \overline{\Phi}_0$ and the infimum of the norm of $\nabla f$ on $\overline{\Phi}_0 \setminus \mathring{B}(C,\delta/3)$ is equal to $\nu$, it must be that $x(t^*) \in \mathring{B}(C,\delta/3)$. Hence there exists $x^* \in C$ such that $\|x(t^*)-x^*\|\leqslant \delta/3$.

\begin{subequations}
    \begin{align}
        2m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) & = 2m~ \psi^{-1}\left(\frac{1}{8m} \epsilon - \frac{L}{2}\frac{\epsilon}{5mL} \right) \label{eq:decrease_discrete_a} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m}(\epsilon-\delta) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_b} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \left(\|x_K-x^*\|-\|x_{k^*}-x^*\|\right) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_c} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \|x_K-x_{k^*}\| - \frac{L\bar{\alpha}}{2} \right) \label{eq:decrease_discrete_d} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m}\sum_{k=k^*}^{K-1} \|x_{k+1}-x_k\| - \frac{L}{2}\max_{k=0,\hdots,K-1} \alpha_k \right) \label{eq:decrease_discrete_e} \\
        & \leqslant f(x_{k^*}) - f(x_{K-1}) \label{eq:decrease_discrete_f} \\
        & \leqslant m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) + \max_C f - f(x_{K-1}). \label{eq:decrease_discrete_g}
    \end{align}
\end{subequations}
Above, the arguments of $\psi^{-1}$ in \eqref{eq:decrease_discrete_a} are equal. \eqref{eq:decrease_discrete_b} through \eqref{eq:decrease_discrete_e} rely on the fact that $\psi^{-1}$ is an increasing function. \eqref{eq:decrease_discrete_b} is due to $\delta<\epsilon/2$. \eqref{eq:decrease_discrete_c} holds because $x_K \notin \mathring{B}(C,\epsilon)$, $x^* \in C$, and $x_{k^*} \in B(x^*,\delta)$. \eqref{eq:decrease_discrete_d} and \eqref{eq:decrease_discrete_e} are consequences of the triangular inequality. \eqref{eq:decrease_discrete_f} is due to the length formula \eqref{eq:length_discrete_K} and the fact that $x_{k^*},\hdots,x_{K-1} \in \mathring{B}(C,\epsilon) \subset \mathring{B}(\overline{\Phi}_0,\epsilon)$. Finally, \eqref{eq:decrease_discrete_g} is due to $x_{k^*}\in B(C,\delta)$ and \eqref{eq:f_bound_discrete}. We remark that $K\geqslant k^*+2$ since $\|x_{k^*+1}-x^*\| \leqslant \|x_{k^*+1}-x_{k^*}\| +\|x_{k^*}-x^*\| \leqslant \alpha_{k^*}\|\nabla f(x_{k^*})\|+\delta \leqslant (\delta/(5mL))L+\delta < \epsilon$. Since $x_0,\hdots,x_{K-2} \in \mathring{B}(\overline{\Phi}_0,\epsilon)$ and $x_{K-1}$ belongs to 
\begin{equation*}
    X_1 := B(C,\epsilon) \bigcap \left\{ x \in \mathbb{R}^n : f(x) \leqslant \max_{C} f - m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) \right\},    
\end{equation*}

by the length formula \eqref{eq:length_discrete_K} and the definition of $\sigma(\cdot,\cdot)$ in \eqref{eq:sup_discrete_X_0} we have
    \begin{align*}
            \sum_{k=0}^\infty \|x_{k+1}-x_k\| & = \sum_{k=0}^{K-2} \|x_{k+1}-x_k\| + \sum_{k=K-1}^\infty \|x_{k+1}-x_k\| \\
            & \leqslant 4m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(\overline{\Phi}_0,\epsilon)} f\right) \right) + 2mL\bar{\alpha} + \max\{0,\sigma(X_1,\bar{\alpha})\}.
    \end{align*}
Note that the inequality still holds if $K = \infty$ or $\sum_{k=0}^{\infty} \alpha_k \leqslant T$. Hence
\begin{equation*}
    \sigma(X_0,\bar{\alpha}) ~\leqslant~ 4m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(\overline{\Phi}_0,\epsilon)} f\right) \right) + 2mL\bar{\alpha} + \max\{0,\sigma(X_1,\bar{\alpha})\}.
\end{equation*}

\begin{definition}
\label{def:lipschitz}
A function $f:\mathbb{R}^n\rightarrow\mathbb{R}^m$ is locally Lipschitz if for all $a \in \mathbb{R}^n$, there exist $r>0$ and $L>0$ such that 
\begin{equation*}
        \forall x,y \in B(a,r), ~~~ \|f(x)-f(y)\| \leqslant L \|x-y\|.
    \end{equation*}
\end{definition}

\begin{definition}
    \label{def:Clarke}
    \cite[Chapter 2]{clarke1990}
    Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function. The Clarke subdifferential is the set-valued mapping $\partial f:\mathbb{R}^n\rightrightarrows\mathbb{R}^n$ defined for all $x \in \mathbb{R}^n$ by
    $\partial f(x) := \{ s \in \mathbb{R}^n : f^\circ(x,h) \geqslant \langle s , h \rangle, ~ \forall h\in \mathbb{R}^n \}$ where
\begin{equation*}
    f^\circ(x,h) := \limsup_{\tiny\begin{array}{c} y\rightarrow x \\
    t \searrow 0
    \end{array}
    } \frac{f(y+th)-f(y)}{t}.
\end{equation*}
\end{definition}

\begin{definition}
    \label{def:absolute_continuity} 
    \cite[Definition 1 p. 12]{aubin1984differential}
    Given some real numbers $a\leqslant b$, a function $x:[a,b]\rightarrow\mathbb{R}^n$ is absolutely continuous if for all $\epsilon>0$, there exists $\delta>0$ such that, for any finite collection of disjoint subintervals $[a_1,b_1],\hdots,[a_m,b_m]$ of $[a,b]$ such that $\sum_{i=1}^m b_i-a_i \leqslant \delta$, we have $\sum_{i=1}^m \|x(b_i) - x(a_i)\| \leqslant \epsilon$.
\end{definition}

\begin{definition}
\label{def:trajectory}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function. Let $(S,\leqslant)$ be the set of absolutely continuous functions $x:[0,T)\rightarrow\mathbb{R}^n$ where $0<T\leqslant \infty$ such that  
\begin{equation*}
    x'(t) \in -\partial f(x(t)), ~~~\mathrm{for~a.e.}~t\in (0,T),
\end{equation*}
equipped with the partial order $\leqslant$ defined by $x_1:[0,T_1)\rightarrow\mathbb{R}^n$ is less than or equal to $x_2:[0,T_2)\rightarrow\mathbb{R}^n$ if and only if $T_1\leqslant T_2$ and $x_1(t) = x_2(t)$ for all $t\in [0,T_1)$. 
We refer to maximal elements of $(S,\leqslant)$ as continuous subgradient trajectories.
\end{definition}

\begin{definition}
\label{def:bounded_trajectory}
A continuous subgradient trajectory $x: [0,T) \rightarrow \mathbb{R}^n$ where $0< T\leqslant \infty$ is bounded if there exists $c>0$ such that $\|x(t)\| \leqslant c$ for all $t\in [0,T)$.
\end{definition}

\begin{remark}
\label{rem:tracking}
If $X_0$ is a singleton $\{x_0\}$ and $x:[0,\hat{T})\rightarrow \mathbb{R}^n$ is a gradient trajectory initialized at $x_0$, then one may remove the assumption that $f$ is lower bounded in Proposition \ref{prop:tracking} and instead require that $T \in (0,\hat{T})$. In that case, $\sigma_T(X_0)=\int_0^T \|x'(t)\|dt < \infty$ since $\nabla f$ is Lipschitz continuous on the bounded set $x([0,T])$.
\end{remark}

\begin{definition}
\label{def:o-minimal}
\cite[Definition p. 503-506]{van1996geometric}
An o-minimal structure on the real field is a sequence $S = (S_k)_{k \in \mathbb{N}}$ such that for all $k \in \mathbb{N}$:
\begin{enumerate}
    \item $S_k$ is a boolean algebra of subsets of $\mathbb{R}^k$, with $\mathbb{R}^k \in S_k$;
    \item $S_k$ contains the diagonal $\{(x_1,\hdots,x_k) \in \mathbb{R}^k : x_i = x_j\}$ for $1\leqslant i<j \leqslant k$;
    \item If $A\in S_k$, then $A\times \mathbb{R}$ and $\mathbb{R}\times A$ belong to $S_{k+1}$;
    \item If $A \in S_{k+1}$ and $\pi:\mathbb{R}^{k+1}\rightarrow\mathbb{R}^k$ is the projection onto the first $k$ coordinates, then $\pi(A) \in S_k$;
    \item $S_3$ contains the graphs of addition and multiplication;
    \item $S_1$ consists exactly of the finite unions of open intervals and singletons. 
\end{enumerate}
\end{definition}

\begin{theorem}
\label{thm:convergence}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a definable differentiable function whose gradient is locally Lipschitz. The following statements are equivalent:
\begin{enumerate}
    \item For all $x_0 \in \mathbb{R}^n$, there exist $\bar{\alpha}>0$ and $c>0$ such that for all $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by 
    \begin{equation}
    \label{eq:gradient_method}
        x_{k+1} = x_k - \alpha_k \nabla f(x_k), ~~~\forall k \in \mathbb{N},
    \end{equation}
    satisfies $\|x_k\|\leqslant c$ for all $k \in \mathbb{N}$.
    \item For all $0< T \leqslant \infty$ and any differentiable function $x:[0,T)\rightarrow\mathbb{R}^n$ such that
    \begin{equation*}
        x'(t) = -\nabla f(x(t)), ~~~ \forall t \in (0,T),
    \end{equation*}
    there exists $c>0$ such that $\|x(t)\| \leqslant c$ for all $t\in [0,T)$.
    \item For any bounded subset $X_0$ of $\mathbb{R}^n$, there exist $\bar{\alpha}>0$ and $c>0$ such that, for all $\alpha_0,\alpha_1,\alpha_2,\hdots \in (0,\bar{\alpha}]$ and $x_0 \in X_0$, the sequence $x_0,x_1,x_2,\hdots \in \mathbb{R}^n$ defined by \eqref{eq:gradient_method} obeys 
    \begin{equation*}
        \sum_{k=0}^{\infty} \|x_{k+1}-x_k\| \leqslant c.
    \end{equation*}
\end{enumerate}
\end{theorem}

