\begin{lemma}
\label{lemma:uniform_length}
If a locally Lipschitz definable function has bounded continuous subgradient trajectories, then continuous subgradient trajectories initialized in a bounded set have uniformly bounded lengths.
\end{lemma}

\begin{proposition}
\label{prop:existence_trajectory}
Locally Lipschitz functions have at least one continuous subgradient trajectory for every initial point.
\end{proposition}

\begin{proof}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R}$ be a locally Lipschitz function and let $x_0\in\mathbb{R}^n$. Since $f$ is locally Lipschitz, the set-valued function $-\partial f$ is upper semicontinuous \cite[2.1.5 Proposition (d) p. 29]{clarke1990} with nonempty, compact and convex values \cite[2.1.2 Proposition (a) p. 27]{clarke1990}. By virtue of \cite[Theorem 3 p. 98]{aubin1984differential}, there exist $\epsilon>0$ and an absolutely continuous function $x:[0,\epsilon)\rightarrow\mathbb{R}^n$ such that  
\begin{equation*}
    x'(t) \in -\partial f(x(t)), ~\mathrm{for~a.e.}~ t\in (0,\epsilon),~~~ x(0) = x_0.
\end{equation*}
Let $S_{x_0}$ be the set of functions in $S$ from Definition \ref{def:trajectory} such that $x(0) = x_0$. Then $S_{x_0} \neq \emptyset$. Let $P$ be a nonempty totally ordered subset of $S_{x_0}$. Let $0<T \leqslant\infty$ be the supremum of the endpoints of the domains of all functions in $P$. Consider the function $x:[0,T)\rightarrow\mathbb{R}^n$ such that for all $\bar{x}:[0,\overline{T})\rightarrow \mathbb{R}^n$ in $P$ we have $x(t) := \bar{x}(t)$ for all $t\in [0,\overline{T})$. It is well defined and it is an upper bound of $P$ in $S_{x_0}$. By virtue of Zorn's lemma \cite[Corollary 2.5 p. 884]{lang2012algebra}, $S_{x_0}$ contains a maximal element. \end{proof}

