\end{subequations}
Above, \eqref{eq:decrease_continuous_a} through \eqref{eq:decrease_continuous_d} rely on the fact that $\psi^{-1}$ is increasing. \eqref{eq:decrease_continuous_a} is due to $\delta < \epsilon/2$. \eqref{eq:decrease_continuous_b} holds because $\|x_k(T_k)-x^*\|\geqslant \epsilon$ by continuity of $x_k(\cdot)$ and $x_k(t^*) \in B(x^*,\delta)$. \eqref{eq:decrease_continuous_c} is a consequence of the triangular inequality. \eqref{eq:decrease_continuous_d} holds because $x_k(\cdot)$ is absolutely continuous. \eqref{eq:decrease_continuous_e} is due to Proposition \ref{prop:length_continuous} and the fact that $x_k(t) \in B(x^*,\epsilon)$ for all $t \in [t^*,T_k]$ by continuity of $x_k(\cdot)$. Finally, \eqref{eq:decrease_continuous_f} is due to $x_k(t^*)\in B(x^*,\delta)$ and \eqref{eq:f_bound_continuous}. Since $x_k(t) \in B(\overline{x(\mathbb{R}_+)},\epsilon)$ for all $t\in [0,T_k]$ and $x_k(T_k)$ belongs to
\begin{equation*}
     X_1 := B(x^*,\epsilon) \bigcap \left\{ x \in \mathbb{R}^n : f(x) \leqslant f(x^*) - m~\psi^{-1}\left(\frac{\epsilon}{4m}\right) \right\},
\end{equation*}

by Proposition \ref{prop:length_continuous} and the definition of $\sigma(\cdot)$ in \eqref{eq:sup_trajectory} we have 
    \begin{align*}
            \int_0^{\infty} \|x_k'(t)\|dt & = \int_{0}^{T_k} \|x_k'(t)\|dt + \int_{T_k}^{\infty} \|x_k'(t)\|dt \\
            & \leqslant 2m~\psi\left( \frac{1}{2m} \left(\sup_{X_0} f - \min_{B(x^*,\epsilon)} f\right) \right) + \max\{0,\sigma(X_1)\}.
    \end{align*}
