\begin{subequations}
    \begin{align}
        2m~\psi^{-1}\left(\frac{\epsilon}{40m}\right) & = 2m~ \psi^{-1}\left(\frac{1}{8m} \epsilon - \frac{L}{2}\frac{\epsilon}{5mL} \right) \label{eq:decrease_discrete_a} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m}(\epsilon-\delta) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_b} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \left(\|x_K-x^*\|-\|x_{k^*}-x^*\|\right) - \frac{L\alpha_\delta}{2} \right) \label{eq:decrease_discrete_c} \\
        & \leqslant 2m~ \psi^{-1}\left(\frac{1}{4m} \|x_K-x_{k^*}\| - \frac{L\bar{\alpha}}{2} \right) \label{eq:decrease_discrete_d} \\
